/* widget: Post Carousel */

#uc_post_carousel_elementor_bb3d4de-wrapper{
  min-height:1px;
}

#uc_post_carousel_elementor_bb3d4de *{
  box-sizing:border-box;
}

#uc_post_carousel_elementor_bb3d4de .ue-grid-item-category a{
  white-space: nowrap;
}


#uc_post_carousel_elementor_bb3d4de{
  position:relative;
}

.uc_post_title{
  font-size:21px;
}

#uc_post_carousel_elementor_bb3d4de .ue-item{
  transition:0.3s;
  position:relative;
}

#uc_post_carousel_elementor_bb3d4de .uc_image_carousel_placeholder{
  position:relative;
}

#uc_post_carousel_elementor_bb3d4de .ue_pos_carousel_image_overlay{
  position:absolute;
  top:0;
  bottom:0;
  left:0;
  right:0;
  transition:0.3s;
}

#uc_post_carousel_elementor_bb3d4de .owl-stage{
  display:flex;
}

#uc_post_carousel_elementor_bb3d4de .uc_image_carousel_container_holder{
  display: flex;
  flex-direction: column;
  height: 100%;
}

#uc_post_carousel_elementor_bb3d4de .uc_image_carousel_content{
  flex-grow: 1;
  }


#uc_post_carousel_elementor_bb3d4de .uc_carousel_item{
  overflow:hidden;
}

#uc_post_carousel_elementor_bb3d4de .owl-nav .owl-prev{
    position:absolute;
    display:inline-block;
    text-align:center;  	


}
#uc_post_carousel_elementor_bb3d4de .owl-nav .owl-next{
  position:absolute;
  display:inline-block;
  text-align:center;

}


#uc_post_carousel_elementor_bb3d4de .owl-dots {
  overflow:hidden;
  display:flex !important;
}

#uc_post_carousel_elementor_bb3d4de .owl-dot {
  border-radius:50%;
  display:inline-block;
  padding: 0;
}

#uc_post_carousel_elementor_bb3d4de .uc_more_btn{
  display:inline-block;
  text-align:center;
  text-decoration:none;
}  

#uc_post_carousel_elementor_bb3d4de .uc_more_btn svg{
  width:1em;
  height:1em;
}

#uc_post_carousel_elementor_bb3d4de .uc_image_carousel_placeholder{
  overflow:hidden;
}
#uc_post_carousel_elementor_bb3d4de .uc_image_carousel_placeholder img{
  display:block;
  width:100%;
}

#uc_post_carousel_elementor_bb3d4de .uc_image_carousel_content {
  display:flex;
  flex-direction:column;
}











#uc_post_carousel_elementor_bb3d4de .ue-meta-data{  
  display:flex !important;
  flex-wrap: wrap;
  line-height:1em;
}

#uc_post_carousel_elementor_bb3d4de .ue-grid-item-meta-data{
      display:inline-flex;
      align-items:center;
}

.ue-grid-item-meta-data{
  font-size:12px;
}

#uc_post_carousel_elementor_bb3d4de .ue-grid-item-meta-data-icon{
  line-height:1em;
}

#uc_post_carousel_elementor_bb3d4de .ue-grid-item-meta-data-icon svg{
  width:1em;
  height:1em;
}

#uc_post_carousel_elementor_bb3d4de .ue-debug-meta{
  padding:10px;
  border:1px solid red;
  position:relative;
  line-height:1.5em;
  font-size:11px;
  width:100%;
}

  #uc_post_carousel_elementor_bb3d4de .ue-item a.ue-link-all-item  {
    position:absolute;
    top:0;
    right:0;
    bottom:0;
    left:0;
    display:block;
  }

	#uc_post_carousel_elementor_bb3d4de .owl-stage        {
            transition-timing-function: linear!important;
        }

#uc_post_carousel_elementor_bb3d4de .owl-nav .owl-prev.disabled,
#uc_post_carousel_elementor_bb3d4de .owl-nav .owl-next.disabled {
   display: none;
}

