/* widget: Post List */



#uc_post_list_elementor_4b64bdf{
  display:grid;
}

#uc_post_list_elementor_4b64bdf .uc_post_list_image div{
  background-size:cover;
  background-position:center;
}

.uc_post_list .uc_post_list_box{
	position: relative;
	overflow: hidden;
	display: flex;
}

#uc_post_list_elementor_4b64bdf .uc_post_list_image{
  flex-grow:0;
  flex-shrink:0;
  overflow: hidden;
}

#uc_post_list_elementor_4b64bdf .uc_post_list_image img{
  width:100%;
  height:100%;
  display:block;
  transition:0.3s;  
  position: relative;
  z-index: 1;
}

.uc_post_list_title a{
    position: relative;
    z-index: 1;
	color: #333333;
    display: block;
}

.uc_post_list_date{
	font-size: 12px;
}

#uc_post_list_elementor_4b64bdf .uc_post_list_content{
  display:flex;
  flex-direction:column;
  flex:1;
}

#uc_post_list_elementor_4b64bdf .uc_more_btn{
  text-align:center;
  text-decoration:none;
  transition:0.3s;
  position: relative;
  z-index: 1;
}

#uc_post_list_elementor_4b64bdf .button-on-side{
  display:flex;
  align-items:center;
}

#uc_post_list_elementor_4b64bdf .ue-grid-item-category{
  display: flex;
  align-items: center;
}

.ue-grid-item-category a{
  display:inline-block;
  font-size:10px;
  text-transform:uppercase;
  white-space: nowrap;
}

#uc_post_list_elementor_4b64bdf .ue-meta-data{  
  display:flex;
  flex-wrap: wrap;
  line-height:1em;
}

#uc_post_list_elementor_4b64bdf .ue-grid-item-meta-data{
      display:inline-flex;
      align-items:center;
}

.ue-grid-item-meta-data{
  font-size:12px;
}

#uc_post_list_elementor_4b64bdf .ue-grid-item-meta-data-icon{
  line-height:1em;
}

#uc_post_list_elementor_4b64bdf .ue-grid-item-meta-data-icon svg{
  width:1em;
  height:1em;
} 

#uc_post_list_elementor_4b64bdf .ue-debug-meta{
  padding:10px;
  border:1px solid red;
  position:relative;
  line-height:1.5em;
  font-size:11px;
  width:100%;
}

.uc-remote-parent .uc_post_list_box{
	cursor:pointer;
}

#uc_post_list_elementor_4b64bdf .ue-post-link-overlay{
  display:block;
  position:absolute;
  top:0;
  bottom:0;
  right:0;
  left:0;
}

.unlimited-elements-background-overlay{
				position:absolute;
				top:0px;
				left:0px;
				width:100%;
				height:100%;
				z-index:0;
			}

			.unlimited-elements-background-overlay.uc-bg-front{
				z-index:999;
			}

